class Solution:
    def findAll(self, text: str, tag: str) -> List[int]:
        n, m = len(text), len(tag)
        out = []
        for i in range(n - m + 1):
            j = 0
            while j < m and text[i + j] == tag[j]:
                j += 1
            if j == m:
                out.append(i)
        return out

code.java:
class Solution {
    public int[] findAll(String text, String tag) {
        int n = text.length(), m = tag.length();
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i + m <= n; i++) {
            int j = 0;
            while (j < m && text.charAt(i + j) == tag.charAt(j)) j++;
            if (j == m) out.add(i);
        }
        return out.stream().mapToInt(x -> x).toArray();
    }
}

