class Solution:
    def findAll(self, text: str, tag: str) -> List[int]:
        m = len(tag)
        fail, k = [0] * m, 0
        for i in range(1, m):
            while k and tag[i] != tag[k]:
                k = fail[k - 1]
            if tag[i] == tag[k]:
                k += 1
            fail[i] = k
        out, k = [], 0
        for i, c in enumerate(text):
            while k and c != tag[k]:
                k = fail[k - 1]
            if c == tag[k]:
                k += 1
            if k == m:
                out.append(i - m + 1)
                k = fail[k - 1]
        return out

