class Solution {
    public int[] findAll(String text, String tag) {
        int n = text.length(), m = tag.length(), k = 0;
        int[] fail = new int[m];
        for (int i = 1; i < m; i++) {
            while (k > 0 && tag.charAt(i) != tag.charAt(k)) k = fail[k - 1];
            if (tag.charAt(i) == tag.charAt(k)) k++;
            fail[i] = k;
        }
        List<Integer> out = new ArrayList<>();
        k = 0;
        for (int i = 0; i < n; i++) {
            char c = text.charAt(i);
            while (k > 0 && c != tag.charAt(k)) k = fail[k - 1];
            if (c == tag.charAt(k)) k++;
            if (k == m) { out.add(i - m + 1); k = fail[k - 1]; }
        }
        return out.stream().mapToInt(x -> x).toArray();
    }
}

