int* findAll(char* text, char* tag, int* returnSize) {
    int n = strlen(text), m = strlen(tag), k = 0, count = 0;
    int* fail = calloc(m, sizeof(int));
    for (int i = 1; i < m; i++) {
        while (k > 0 && tag[i] != tag[k]) k = fail[k - 1];
        if (tag[i] == tag[k]) k++;
        fail[i] = k;
    }
    int* out = malloc((n + 1) * sizeof(int));
    k = 0;
    for (int i = 0; i < n; i++) {
        while (k > 0 && text[i] != tag[k]) k = fail[k - 1];
        if (text[i] == tag[k]) k++;
        if (k == m) { out[count++] = i - m + 1; k = fail[k - 1]; }
    }
    free(fail);
    *returnSize = count;
    return out;
}
